import optuna

optuna.logging.set_verbosity(optuna.logging.WARNING)

def objective(trial):
    x = trial.suggest_float("x", -10, 10)
    return (x - 2) ** 2

class StopWhenStale:
    def __init__(self, patience):
        self.patience = patience
    def __call__(self, study, trial):
        if trial.number - study.best_trial.number >= self.patience:
            study.stop()                     # no improvement for `patience` trials

study = optuna.create_study(sampler=optuna.samplers.TPESampler(seed=0))
study.enqueue_trial({"x": 1.5})              # evaluate a known-good guess first
study.optimize(objective, n_trials=500, timeout=60, callbacks=[StopWhenStale(25)])

print(study.trials[0].params)                # {'x': 1.5}
print(len(study.trials) < 500)               # True: stopped early by the callback

import numpy as np
import optuna

optuna.logging.set_verbosity(optuna.logging.WARNING)

class LocalSearchSampler(optuna.samplers.BaseSampler):
    # Sample near the best trial so far; fall back to random sampling.
    def __init__(self, seed=None):
        self._random = optuna.samplers.RandomSampler(seed=seed)
        self._rng = np.random.default_rng(seed)
    def infer_relative_search_space(self, study, trial):
        return {}
    def sample_relative(self, study, trial, search_space):
        return {}
    def sample_independent(self, study, trial, name, dist):
        done = study.get_trials(deepcopy=False, states=(optuna.trial.TrialState.COMPLETE,))
        if len(done) < 5 or not isinstance(dist, optuna.distributions.FloatDistribution):
            return self._random.sample_independent(study, trial, name, dist)
        center = study.best_params[name]
        width = (dist.high - dist.low) * 0.05
        return float(min(max(self._rng.normal(center, width), dist.low), dist.high))

study = optuna.create_study(sampler=LocalSearchSampler(seed=0))
study.optimize(lambda t: (t.suggest_float("x", -10, 10) - 4.2) ** 2, n_trials=60)
print(round(study.best_params["x"], 2))      # close to 4.2
